// ============================================
// VENUE REVIEW REPORT - CSV PROCESSOR
// WITH DYNAMIC FISCAL CALENDAR ENGINE
// ============================================

// ---- FISCAL CALENDAR ENGINE ----
const FY_ANCHOR = new Date('2024-07-01T00:00:00');
const FY_DAYS = 364;
const MS_PER_DAY = 86400000;

function getFiscalInfo(dateObj) {
  // Normalize to midnight
  const d = new Date(dateObj.getFullYear(), dateObj.getMonth(), dateObj.getDate());
  const daysSinceAnchor = Math.floor((d - FY_ANCHOR) / MS_PER_DAY);

  const fyIndex = Math.floor(daysSinceAnchor / FY_DAYS);
  const dayInFY = daysSinceAnchor % FY_DAYS;

  const fyStartYear = 2024 + fyIndex;
  const fyLabel = 'FY' + String(fyStartYear % 100).padStart(2, '0') + '-' + String((fyStartYear + 1) % 100).padStart(2, '0');

  const weekNum = Math.floor(dayInFY / 7) + 1;
  const periodNum = Math.floor((weekNum - 1) / 4) + 1;
  const weekInPeriod = ((weekNum - 1) % 4) + 1;

  const fyStart = new Date(FY_ANCHOR.getTime() + fyIndex * FY_DAYS * MS_PER_DAY);
  const fyEnd = new Date(fyStart.getTime() + (FY_DAYS - 1) * MS_PER_DAY);

  const weekStart = new Date(fyStart.getTime() + (weekNum - 1) * 7 * MS_PER_DAY);
  const weekEnd = new Date(weekStart.getTime() + 6 * MS_PER_DAY);

  const periodStartWk = (periodNum - 1) * 4 + 1;
  const periodStart = new Date(fyStart.getTime() + (periodStartWk - 1) * 7 * MS_PER_DAY);
  const periodEnd = new Date(periodStart.getTime() + 27 * MS_PER_DAY);

  return {
    fyLabel, fyStartYear, fyStart, fyEnd,
    periodNum, periodLabel: 'P' + String(periodNum).padStart(2, '0'),
    periodStart, periodEnd,
    weekNum, weekLabel: 'WK' + weekNum,
    weekInPeriod,
    weekStart, weekEnd
  };
}



function parseCSV(csvText) {
  const lines = csvText.split('\n');
  if (lines.length < 2) return [];

  const header = parseCSVLine(lines[0]);
  const rows = [];

  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const values = parseCSVLine(lines[i]);
    const row = {};
    header.forEach((col, idx) => {
      row[col.trim()] = values[idx] ? values[idx].trim() : '';
    });
    rows.push(row);
  }
  return rows;
}

function parseCSVLine(line) {
  const result = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '"') {
      if (inQuotes && i + 1 < line.length && line[i + 1] === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === ',' && !inQuotes) {
      result.push(current);
      current = '';
    } else {
      current += char;
    }
  }
  result.push(current);
  return result;
}

function parseDate(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  return isNaN(d.getTime()) ? null : d;
}

function formatDate(d) {
  return d.toISOString().split('T')[0];
}

function getOrdinalSuffix(day) {
  if (day > 3 && day < 21) return 'th';
  switch (day % 10) {
    case 1: return 'st';
    case 2: return 'nd';
    case 3: return 'rd';
    default: return 'th';
  }
}

function formatDateDisplay(d) {
  const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const day = d.getDate();
  return months[d.getMonth()] + ' ' + day + getOrdinalSuffix(day);
}

function getDayName(d) {
  return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d.getDay()];
}

function computeMetrics(allReviews, weekStart, weekEnd, periodStart, periodEnd, fyStart, fyEnd) {
  const wsDate = new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate());
  const weDate = new Date(weekEnd.getFullYear(), weekEnd.getMonth(), weekEnd.getDate());
  weDate.setHours(23, 59, 59, 999);

  const psDate = new Date(periodStart.getFullYear(), periodStart.getMonth(), periodStart.getDate());
  const peDate = new Date(periodEnd.getFullYear(), periodEnd.getMonth(), periodEnd.getDate());
  peDate.setHours(23, 59, 59, 999);

  const fysDate = new Date(fyStart.getFullYear(), fyStart.getMonth(), fyStart.getDate());
  const fyeDate = new Date(fyEnd.getFullYear(), fyEnd.getMonth(), fyEnd.getDate());
  fyeDate.setHours(23, 59, 59, 999);

  const weekReviews = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= wsDate && d <= weDate;
  });

  const activeWeek = weekReviews.filter(r => !r['Deleted'] || r['Deleted'].trim() === '');
  const deletedWeek = weekReviews.filter(r => r['Deleted'] && r['Deleted'].trim() !== '');

  const weeklyAvg = activeWeek.length > 0 
    ? Math.round((activeWeek.reduce((sum, r) => sum + parseFloat(r['Rating']), 0) / activeWeek.length) * 100) / 100 
    : 0;

  const ptdReviews = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= psDate && d <= peDate && (!r['Deleted'] || r['Deleted'].trim() === '');
  });
  const ptdAvg = ptdReviews.length > 0
    ? Math.round((ptdReviews.reduce((sum, r) => sum + parseFloat(r['Rating']), 0) / ptdReviews.length) * 100) / 100
    : 0;

  const ytdReviews = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= fysDate && d <= fyeDate && (!r['Deleted'] || r['Deleted'].trim() === '');
  });
  const ytdAvg = ytdReviews.length > 0
    ? Math.round((ytdReviews.reduce((sum, r) => sum + parseFloat(r['Rating']), 0) / ytdReviews.length) * 100) / 100
    : 0;

  const ratingDist = {};
  for (let i = 5; i >= 1; i--) {
    const count = activeWeek.filter(r => Math.round(parseFloat(r['Rating'])) === i).length;
    const pct = activeWeek.length > 0 ? Math.round((count / activeWeek.length) * 100) : 0;
    ratingDist[i] = { count, pct };
  }

  const sources = {};
  activeWeek.forEach(r => {
    const src = r['Source'] || 'Unknown';
    sources[src] = (sources[src] || 0) + 1;
  });

  const ptdDeleted = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= psDate && d <= peDate && r['Deleted'] && r['Deleted'].trim() !== '';
  }).length;

  const ytdDeleted = allReviews.filter(r => {
    const d = parseDate(r['Published']);
    return d && d >= fysDate && d <= fyeDate && r['Deleted'] && r['Deleted'].trim() !== '';
  }).length;

  // Dynamic name detection: find any capitalized word (3+ letters) that looks like a first name
  // The reviewer who reads the report can remove any false positives
  const nameMentions = {};
  const stopWords = new Set([
    'the','and','but','for','are','was','were','been','being','have','has','had',
    'will','would','could','should','shall','may','might','can','did','does','done',
    'not','this','that','these','those','with','from','into','upon','about','after',
    'before','above','below','between','under','over','through','during','while',
    'where','when','which','what','who','whom','whose','how','than','then','here',
    'there','each','every','both','few','more','most','other','some','such','only',
    'same','also','just','back','been','come','even','give','good','great','just',
    'know','like','look','make','many','much','need','next','open','part','play',
    'real','said','take','tell','think','very','want','well','went','work','year',
    'best','better','came','first','last','long','made','right','still','thing',
    'time','used','way','our','out','all','any','day','got','her','him','his','its',
    'let','new','now','off','old','one','own','put','run','say','she','too','try',
    'two','use','your','they','them','their','mine','ours','yours','really','always',
    'never','sometimes','maybe','please','thank','thanks','great','amazing','awesome',
    'wonderful','terrible','horrible','worst','love','loved','loved','hate','hated',
    'place','night','drinks','food','drink','staff','service','experience','fun',
    'birthday','party','music','games','golf','mini','course','courses','bar',
    'bartender','server','host','manager','wait','table','google','yelp','tripadvisor',
    'definitely','absolutely',
    'highly','recommend','recommended','visited','visit','went','going','came',
    'saturday','sunday','monday','tuesday','wednesday','thursday','friday',
    'january','february','march','april','june','july','august','september',
    'october','november','december','may'
  ]);

  activeWeek.forEach(r => {
    const text = r['Review'] || '';
    // Find capitalized words that are 3+ chars and not at sentence start
    const words = text.match(/(?<=[a-z.,!?;:]\s+)[A-Z][a-z]{2,}/g) || [];
    // Also check words after common patterns like "named", "by", "our", "ask for", "shoutout to"
    const namedPatterns = text.match(/(?:named|name is|name was|shout ?out to|ask for|helped by|served by|bartender|server|host)\s+([A-Z][a-z]{2,})/gi) || [];

    const allNames = [...words];
    namedPatterns.forEach(match => {
      const parts = match.split(/\s+/);
      const last = parts[parts.length - 1];
      if (last && last[0] === last[0].toUpperCase()) allNames.push(last);
    });

    allNames.forEach(word => {
      const clean = word.replace(/[^a-zA-Z]/g, '');
      if (clean.length >= 3 && !stopWords.has(clean.toLowerCase())) {
        nameMentions[clean] = (nameMentions[clean] || 0) + 1;
      }
    });
  });

  const dailyBreakdown = {};
  activeWeek.forEach(r => {
    const d = parseDate(r['Published']);
    if (!d) return;
    const dayKey = formatDate(d);
    if (!dailyBreakdown[dayKey]) {
      dailyBreakdown[dayKey] = { date: d, positive: 0, neutral: 0, negative: 0, reviews: [] };
    }
    const rating = parseFloat(r['Rating']);
    if (rating >= 4) dailyBreakdown[dayKey].positive++;
    else if (rating === 3) dailyBreakdown[dayKey].neutral++;
    else dailyBreakdown[dayKey].negative++;
    dailyBreakdown[dayKey].reviews.push(r);
  });

  return {
    totalReviews: activeWeek.length,
    weeklyAvg,
    ptdAvg,
    ptdCount: ptdReviews.length,
    ytdAvg,
    ytdCount: ytdReviews.length,
    deletedThisWeek: deletedWeek.length,
    deletedPTD: ptdDeleted,
    deletedYTD: ytdDeleted,
    ratingDist,
    sources,
    nameMentions,
    dailyBreakdown,
    activeReviews: activeWeek,
    deletedReviews: deletedWeek
  };
}

function formatAuthorName(author) {
  if (!author) return 'Anonymous';
  const parts = author.trim().split(/\s+/);
  if (parts.length === 0) return 'Anonymous';
  if (parts.length === 1) return parts[0];
  return parts[0] + ' ' + parts[1][0] + '.';
}

const items = $input.all();
let csvText = '';
let historyData = { weeks: [] };

for (const item of items) {
  if (item.binary) {
    // Try each binary key (could be 'data', 'file', 'attachment', etc.)
    for (const key of Object.keys(item.binary)) {
      try {
        // n8n stores binary as a reference - use helpers to get buffer
        const binaryObj = item.binary[key];
        let text = '';

        // Method 1: n8n >= 1.x uses await helpers.getBinaryDataBuffer
        if (typeof helpers !== 'undefined' && helpers.getBinaryDataBuffer) {
          const buffer = await helpers.getBinaryDataBuffer(items.indexOf(item), key);
          text = buffer.toString('utf-8');
        }
        // Method 2: Direct base64 data property (older n8n or some modes)  
        else if (binaryObj.data) {
          text = Buffer.from(binaryObj.data, 'base64').toString('utf-8');
        }

        if (!text) continue;

        const trimmed = text.trim();
        if (trimmed.startsWith('{') && trimmed.includes('"weeks"')) {
          historyData = JSON.parse(trimmed);
        } else if (trimmed.includes(',') && (trimmed.toLowerCase().includes('review') || trimmed.toLowerCase().includes('rating') || trimmed.toLowerCase().includes('published'))) {
          csvText = text;
        }
      } catch(e) {
        // Continue to next binary key
      }
    }
  }
}

const allReviews = parseCSV(csvText);
if (allReviews.length === 0) {
  return [{ json: { error: 'No reviews found in CSV' } }];
}

let latestDate = new Date();
const publishedDates = allReviews.map(r => parseDate(r['Published'])).filter(d => d !== null);
if (publishedDates.length > 0) {
  publishedDates.sort((a, b) => a - b);
  latestDate = publishedDates[publishedDates.length - 1];
}

const fiscalInfo = getFiscalInfo(latestDate);
const { fyLabel, fyStart, fyEnd, periodNum, periodLabel, periodStart, periodEnd, weekNum, weekStart, weekEnd } = fiscalInfo;

const metrics = computeMetrics(allReviews, weekStart, weekEnd, periodStart, periodEnd, fyStart, fyEnd);

const wsDisplay = formatDateDisplay(weekStart);
const weDisplay = formatDateDisplay(weekEnd);

let priorWeekMetrics = null;
if (historyData.weeks && historyData.weeks.length > 0) {
  const priorWeek = historyData.weeks.find(w => w.weekNum === (weekNum - 1) && w.fyLabel === fyLabel);
  if (priorWeek) {
    priorWeekMetrics = priorWeek;
  }
}

let ptdHistoryMetrics = null;
if (historyData.weeks && historyData.weeks.length > 0) {
  const periodWeeks = historyData.weeks.filter(w => w.periodNum === periodNum && w.fyLabel === fyLabel && w.weekNum !== weekNum);
  if (periodWeeks.length > 0) {
    const totalReviews = periodWeeks.reduce((sum, w) => sum + (w.totalReviews || 0), 0);
    const avgRating = periodWeeks.length > 0 
      ? Math.round((periodWeeks.reduce((sum, w) => sum + (w.weeklyAvg || 0), 0) / periodWeeks.length) * 100) / 100
      : 0;
    ptdHistoryMetrics = { totalReviews, weeklyAvg: avgRating, weekCount: periodWeeks.length };
  }
}

let priorPeriodMetrics = null;
if (historyData.weeks && historyData.weeks.length > 0) {
  const priorPeriodNum = periodNum - 1;
  const priorPeriodWeeks = historyData.weeks.filter(w => w.periodNum === priorPeriodNum && w.fyLabel === fyLabel);
  if (priorPeriodWeeks.length > 0) {
    const totalReviews = priorPeriodWeeks.reduce((sum, w) => sum + (w.totalReviews || 0), 0);
    const avgRating = priorPeriodWeeks.length > 0
      ? Math.round((priorPeriodWeeks.reduce((sum, w) => sum + (w.weeklyAvg || 0), 0) / priorPeriodWeeks.length) * 100) / 100
      : 0;
    priorPeriodMetrics = { totalReviews, weeklyAvg: avgRating, periodLabel: 'P' + String(priorPeriodNum).padStart(2, '0') };
  }
}

const promoters = metrics.activeReviews.filter(r => parseFloat(r['Rating']) >= 4);
const neutrals = metrics.activeReviews.filter(r => Math.round(parseFloat(r['Rating'])) === 3);
const detractors = metrics.activeReviews.filter(r => parseFloat(r['Rating']) <= 2);

function buildReviewList(reviews) {
  return reviews.map(r => {
    const author = formatAuthorName(r['Author']);
    const rating = parseFloat(r['Rating']);
    const source = r['Source'] || 'Unknown';
    const date = r['Published'] ? r['Published'].split(' ')[0] : '';
    const text = r['Review'] || '(no comment)';
    return '- ' + author + ' (' + rating + '★ ' + source + ', ' + date + '): ' + text;
  }).join('\n');
}

let comparisonStr = '';
if (priorWeekMetrics) {
  const changeReviews = metrics.totalReviews - priorWeekMetrics.totalReviews;
  const pctChange = priorWeekMetrics.totalReviews > 0 
    ? Math.round((changeReviews / priorWeekMetrics.totalReviews) * 100)
    : 0;
  const arrow = changeReviews >= 0 ? '↑' : '↓';
  const changeRating = metrics.weeklyAvg - priorWeekMetrics.weeklyAvg;
  const ratingArrow = changeRating >= 0 ? '↑' : '↓';
  comparisonStr += '\n- Prior Week: ' + priorWeekMetrics.totalReviews + ' reviews at ' + priorWeekMetrics.weeklyAvg + '★ (change: ' + arrow + ' ' + Math.abs(changeReviews) + ' reviews / ' + pctChange + '%, rating: ' + ratingArrow + ' ' + Math.abs(changeRating).toFixed(2) + ')';
}

if (ptdHistoryMetrics) {
  comparisonStr += '\n- Period to Date (' + periodLabel + '): avg ' + ptdHistoryMetrics.weeklyAvg + '★ across ' + ptdHistoryMetrics.weekCount + ' prior weeks';
}

if (priorPeriodMetrics) {
  comparisonStr += '\n- Prior Period (' + priorPeriodMetrics.periodLabel + '): ' + priorPeriodMetrics.totalReviews + ' total reviews at ' + priorPeriodMetrics.weeklyAvg + '★';
}

const claudePrompt = 'You are generating a weekly customer feedback report for {{VENUE_NAME}} ({{VENUE_DESCRIPTION}}).\n\n' +
'REPORT PERIOD: Week ' + weekNum + ' (' + periodLabel + ') — ' + wsDisplay + ' – ' + weDisplay + '\n' +
'FISCAL INFO: ' + fyLabel + '\n\n' +
'COMPUTED METRICS (use these exact numbers):\n' +
'- Total Reviews (active, non-deleted): ' + metrics.totalReviews + '\n' +
'- Weekly Average Rating: ' + metrics.weeklyAvg + '\n' +
'- PTD Average (' + periodLabel + '): ' + metrics.ptdAvg + ' (' + metrics.ptdCount + ' reviews)\n' +
'- YTD Average (' + fyLabel + '): ' + metrics.ytdAvg + ' (' + metrics.ytdCount + ' reviews)\n' +
'- Deleted this week: ' + metrics.deletedThisWeek + '\n' +
'- Deleted ' + periodLabel + ' to date: ' + metrics.deletedPTD + '\n' +
'- Deleted ' + fyLabel + ' to date: ' + metrics.deletedYTD + '\n' +
'- Response Rate: 100%\n' +
'- Response Time: < 1 day\n\n' +
'RATING DISTRIBUTION (non-deleted):\n' +
Object.entries(metrics.ratingDist).map(([r,v]) => r + '★ – ' + v.count + ' (' + v.pct + '%)').join('\n') + '\n\n' +
'SOURCES (non-deleted):\n' +
Object.entries(metrics.sources).map(([s,c]) => s + ' – ' + c).join('\n') + '\n\n' +
(metrics.deletedThisWeek > 0 ? 'DELETED REVIEWS (' + metrics.deletedThisWeek + ' total, excluded from all ratings):\n' + 
  metrics.deletedReviews.map(r => '- ' + formatAuthorName(r['Author']) + ' (' + r['Rating'] + '★ ' + r['Source'] + '): ' + (r['Review'] || '(no comment)')).join('\n') + '\n\n' : '') +
'PROMOTER REVIEWS (4-5★):\n' +
(promoters.length > 0 ? buildReviewList(promoters) : 'None this week') + '\n\n' +
'NEUTRAL REVIEWS (3★):\n' +
(neutrals.length > 0 ? buildReviewList(neutrals) : 'None this week') + '\n\n' +
'DETRACTOR REVIEWS (1-2★):\n' +
(detractors.length > 0 ? buildReviewList(detractors) : 'None this week') + '\n\n' +
'NAME MENTIONS (auto-detected from reviews — reviewer should verify these are actual staff):\n' +
(Object.keys(metrics.nameMentions).length > 0 ? Object.entries(metrics.nameMentions).map(([n,c]) => n + ': ' + c).join('\n') : 'No staff mentioned by name this week') + '\n\n' +
'COMPARISONS FROM HISTORY:\n' +
(comparisonStr || 'No prior data available') + '\n\n' +
'DAILY BREAKDOWN:\n' +
Object.entries(metrics.dailyBreakdown).sort().map(([day, info]) => {
  const dayName = getDayName(info.date);
  return dayName + ' ' + day + ': ' + info.positive + ' positive, ' + info.neutral + ' neutral, ' + info.negative + ' negative';
}).join('\n') + '\n\n' +
'---\n\n' +
'GENERATE THE REPORT USING EXACT METRICS. Format: # FEEDBACK REPORT, ## Venue, ## Week info, ### FEEDBACK BREAKDOWN (with exact numbers), ### REVIEW OBSERVATIONS (4-5★, 3★, 1-2★), ### FEEDBACK TRENDS, ### FOCUS POINTS, ### NAME DROPS';

// Pre-build the full Claude API request body in the Code node
// so n8n doesn't mangle it in HTTP Request expressions
const claudeRequestBody = JSON.stringify({
  model: 'claude-sonnet-4-20250514',
  max_tokens: 4096,
  messages: [{ role: 'user', content: claudePrompt }]
});

return [{
  json: {
    claudePrompt,
    claudeRequestBody,
    metrics: {
      totalReviews: metrics.totalReviews,
      weeklyAvg: metrics.weeklyAvg,
      ptdAvg: metrics.ptdAvg,
      ptdCount: metrics.ptdCount,
      ytdAvg: metrics.ytdAvg,
      ytdCount: metrics.ytdCount,
      deletedThisWeek: metrics.deletedThisWeek,
      deletedPTD: metrics.deletedPTD,
      deletedYTD: metrics.deletedYTD,
      ratingDist: metrics.ratingDist,
      sources: metrics.sources,
      nameMentions: metrics.nameMentions
    },
    weekInfo: {
      fyLabel,
      periodNum,
      periodLabel,
      weekNum,
      weekStart: formatDate(weekStart),
      weekEnd: formatDate(weekEnd),
      weekStartDisplay: wsDisplay,
      weekEndDisplay: weDisplay
    },
    fileName: 'Venue_Review_Report_' + fyLabel + '_' + periodLabel + '_WK' + weekNum + '_' + formatDate(weekStart) + '.md',
    historyData: historyData,
    comparisons: {
      priorWeek: priorWeekMetrics,
      ptdHistory: ptdHistoryMetrics,
      priorPeriod: priorPeriodMetrics
    }
  }
}];

const report = $json.report;
const fileName = $('Process CSV & Build Prompt').first().json.fileName;
const buffer = Buffer.from(report, 'utf-8');
return [{
  json: {fileName, fileSize: buffer.length},
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/markdown',
      fileName: fileName
    }
  }
}];

const reportFile = $('Prepare Report File').first();
const folderId = $json.id;
const processData = $('Process CSV & Build Prompt').first().json;
return [{
  json: {
    folderId,
    fileName: processData.fileName
  },
  binary: reportFile.binary
}];

const processData = $('Process CSV & Build Prompt').first().json;

// Get history from the Process CSV node's stored data
let history = processData.historyData || { weeks: [] };

const newWeekEntry = {
  fyLabel: processData.weekInfo.fyLabel,
  periodNum: processData.weekInfo.periodNum,
  periodLabel: processData.weekInfo.periodLabel,
  weekNum: processData.weekInfo.weekNum,
  weekStart: processData.weekInfo.weekStart,
  weekEnd: processData.weekInfo.weekEnd,
  totalReviews: processData.metrics.totalReviews,
  weeklyAvg: processData.metrics.weeklyAvg,
  deletedThisWeek: processData.metrics.deletedThisWeek,
  ratingDist: processData.metrics.ratingDist,
  sources: processData.metrics.sources,
  generatedAt: new Date().toISOString()
};

history.weeks.push(newWeekEntry);
const jsonStr = JSON.stringify(history, null, 2);
const buffer = Buffer.from(jsonStr, 'utf-8');

return [{
  json: {
    fileName: 'metrics_history.json',
    size: buffer.length
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/json',
      fileName: 'metrics_history.json'
    }
  }
}];

// Normalize FY folder ID from either search result or create result
const item = $input.first();
let folderId;
if (item.json.files && item.json.files.length > 0) {
  folderId = item.json.files[0].id;
} else if (item.json.id) {
  folderId = item.json.id;
}
return [{ json: { id: folderId, source: 'fy_folder' } }];

// Normalize Period folder ID from either search result or create result
const item = $input.first();
let folderId;
if (item.json.files && item.json.files.length > 0) {
  folderId = item.json.files[0].id;
} else if (item.json.id) {
  folderId = item.json.id;
}
return [{ json: { id: folderId, source: 'period_folder' } }];
